def descricao(num, hook, skill, pais, kw, final_card):
    """Descrição pronta: gancho + lição + dica aos pais + palavras-chave + chamada + hashtags."""
    return (f"{hook}\n\n"
            f"📚 O QUE A CRIANÇA APRENDE: {skill}.\n"
            f"👨‍👩‍👧 DICA PARA OS PAIS: {pais}.\n"
            f"🎵 Música infantil original, com letra para cantar junto e legenda em inglês.\n\n"
            f"✅ Conteúdo educativo para crianças: comportamento, boas maneiras, hábitos saudáveis e rotina, "
            f"com mensagem positiva e sem sustos.\n"
            f"👉 Inscreva-se para receber uma nova lição cantada todos os dias!\n\n"
            f"Palavras-chave: {', '.join(kw)}.\n\n"
            f"{HASHTAGS}\n\n"
            f"Aviso: vídeo animado criado com ferramentas de IA, com roteiro e música originais. Conteúdo feito para crianças.")
